  const handleAssistantClick = async () => {
    setAssistantLoading(true);
    setError(null);
    try {
      const isSpecificSong = songTitle.trim().length > 0;
      let prompt = `Act as a Music Intelligence Agent. User requested: "${songTitle}" by "${artistRef}".

      TASK:
      1. USE GOOGLE SEARCH to identify if this is an existing song.
      2. IF EXISTING: Retrieve the EXACT OFFICIAL metadata (BPM, Key, Genre, Subgenre, Mood, Theme, Language).
         - Map the Genre/Subgenre/Mood/Theme to the most accurate professional terms.
      3. IF NEW/FICTIONAL: Suggest optimal parameters based on the title and artist style.

      Return ONLY valid JSON with this structure:
      {
        "genre": ["MainGenre", "SecondaryGenre"], 
        "subgenre": ["SpecificSubgenre1", "SpecificSubgenre2"], 
        "worldMusic": ["Region/Style" or "None"], 
        "moods": ["Mood1", "Mood2", "Mood3"], 
        "themes": ["Theme1", "Theme2"], 
        "tempo": Number, 
        "key": "String (e.g. C# Minor)", 
        "timeSignature": "String (e.g. 4/4)", 
        "lyricLanguage": "String", 
        "durationMinutes": Number
      }`;

      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
            tools: isSpecificSong ? [{ googleSearch: {} }] : [],
            responseMimeType: isSpecificSong ? undefined : "application/json"
        },
      }));

      let text = response.text || "";
      let suggestions;
      try {
          text = text.replace(/```json/g, "").replace(/```/g, "").trim();
          const start = text.indexOf('{');
          const end = text.lastIndexOf('}');
          suggestions = JSON.parse(text.substring(start, end + 1));
      } catch (e) {
          throw new Error("Failed to parse AI suggestions.");
      }

      if (suggestions.genre) {
          const arr = Array.isArray(suggestions.genre) ? suggestions.genre : [suggestions.genre];
          setGenreOptions(prev => Array.from(new Set([...arr, ...prev])));
          setGenres(arr.slice(0, 3));
      }
      if (suggestions.subgenre) {
          const arr = Array.isArray(suggestions.subgenre) ? suggestions.subgenre : [suggestions.subgenre];
          setSubgenreOptions(prev => Array.from(new Set([...arr, ...prev])));
          setSubgenres(arr.slice(0, 3));
      }

      if (suggestions.worldMusic) {
          const arr = Array.isArray(suggestions.worldMusic) ? suggestions.worldMusic : [suggestions.worldMusic];
          setWorldMusicOptions(prev => Array.from(new Set([...arr, ...prev])));
          setWorldMusicInfluences(arr.slice(0, 5));
      }
      if (suggestions.moods) {
          const arr = Array.isArray(suggestions.moods) ? suggestions.moods : [suggestions.moods];
          setMoodOptions(prev => Array.from(new Set([...arr, ...prev])));
          setMoods(arr.slice(0, 5));
      }
      if (suggestions.themes) {
          const arr = Array.isArray(suggestions.themes) ? suggestions.themes : [suggestions.themes];
          setThemeOptions(prev => Array.from(new Set([...arr, ...prev])));
          setThemes(arr.slice(0, 5));
      }

      // Sync menu state with AI suggestions
      if (suggestions.tempo) setTempo(Math.round(Math.max(40, Math.min(220, suggestions.tempo))));
      if (suggestions.key) setKey(KEY_OPTIONS.find(k => suggestions.key.includes(k)) || KEY_OPTIONS[0]);
      if (suggestions.timeSignature && TIME_SIGNATURE_OPTIONS.includes(suggestions.timeSignature)) setTimeSignature(suggestions.timeSignature);
      if (suggestions.lyricLanguage) {
          const matchedLang = LYRIC_LANGUAGE_OPTIONS.find(l => suggestions.lyricLanguage.toLowerCase().includes(l.toLowerCase()));
          if (matchedLang) setLyricLanguage(matchedLang);
      }
      if (suggestions.durationMinutes) setDuration(suggestions.durationMinutes >= 6 ? "8" : "4");

    } catch (e) {
      setError("AI assistant failed. Please try again.");
    } finally {
      setAssistantLoading(false);
    }
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setOutputBlocks([]);
    setSources([]);

    const isSpecificSong = songTitle.trim().length > 0;

    // Convert arrays to comma-separated strings for the prompt
    const genreStr = genres.join(", ") || "General";
    const subgenreStr = subgenres.join(", ") || "General";
    const moodStr = moods.join(", ") || "Varied";
    const themeStr = themes.join(", ") || "General";
    const worldStr = worldMusicInfluences.join(", ") || "None";

    const prompt = `ACT AS A WORLD-CLASS MUSIC PRODUCER.
    Target: "${songTitle}" (Style: "${artistRef}")
    User Input Context: Genre [${genreStr}], Moods [${moodStr}], User Input Tempo: [${tempo} BPM].

    MANDATE:
    1. SYNCHRONIZATION: Use Google Search to find if "${songTitle}" exists. 
       **CRITICAL FOR EXISTING SONGS**: 
       - Retrieve the EXACT lyrics and the EXACT song structure (Verse, Chorus, Bridge, etc.) from reliable sources.
       - You MUST place the specific lyrics into their CORRECT structural sections as performed in the original song.
       - Do NOT rearrange lines or invent a structure that differs from the original recording.
       - Use REAL STUDIO BPM/KEY (OVERRIDE user input).
    2. IF NEW SONG: Use user input to create a creative structure.
    3. METADATA LAYERS: Before lyrics, you MUST generate detailed: 
       - [STRUCTURE] (Format: "Section: Length" ONLY. E.g., "[Intro: 16 bars]")
       - [MELODIC ELEMENTS]
       - [HARMONIC ELEMENTS]
       - [RHYTHMIC ELEMENTS]
       - [INSTRUMENTATION]
    4. CHORD VOCABULARY (CRITICAL):
       - ROCK/METAL/PUNK: You MUST use Power Chords (e.g., [A5], [C#5], [E5]) for distorted riff sections. Do NOT use simple major chords ([A]) when the audio implies a power chord.
       - JAZZ/R&B/NEO-SOUL: You MUST use Extended Chords (e.g., [Cmaj7], [Dm9], [G13b9]) where appropriate.
       - EXISTING SONGS: Do NOT simplify the harmony. If the original recording uses [Asus4] or [D/F#], you MUST transcribe it exactly. Do not dumb it down to [A] or [D].
    5. LEAD SHEET FORMATTING:
       - Chords MUST be placed EXACTLY above the syllable where the change occurs.
       - Do NOT just list chords at the start of the line. Spacing matters.
    6. ARRANGEMENT: In the [LYRICS & ARRANGEMENT] section, include [Instrumentation], [Vocals], and [SFX] tags for every section.

    STRICT FORMAT TEMPLATE (Follow this Pattern):
    [Title: ${songTitle}]
    [Artist: ${artistRef}]
