// --- Optimized MultiSelect Component (Lazy Render & Search) ---
const MultiSelect = ({ label, options, selected, onChange, max = 5 }: { label: string, options: string[], selected: string[], onChange: (val: string[]) => void, max?: number }) => {
  const [filter, setFilter] = useState("");
  const [showAll, setShowAll] = useState(false);

  const toggle = (opt: string) => {
    if (selected.includes(opt)) {
      onChange(selected.filter(s => s !== opt));
    } else {
      if (selected.length < max) {
        onChange([...selected, opt]);
      }
    }
  };

  const filteredOptions = options.filter(opt => opt.toLowerCase().includes(filter.toLowerCase()));
  // Performance hack: Only render top 20 items initially to prevent mobile DOM freeze
  const visibleOptions = showAll || filter.length > 0 ? filteredOptions : filteredOptions.slice(0, 20);
  const hiddenCount = filteredOptions.length - visibleOptions.length;

  return (
    <div className="form-group">
      <div className="label-row">
        <label>{label}</label>
        <span className="count-badge">{selected.length}/{max}</span>
      </div>

      {/* Search Input for filtering huge lists */}
      <input 
        type="text" 
        className="filter-input"
        placeholder={`Search ${label.split('(')[0].trim()}...`} 
        value={filter}
        onChange={(e) => setFilter(e.target.value)}
        style={{marginBottom: '0.8rem', fontSize: '0.9rem', padding: '0.6rem'}}
      />

      <div className="chip-grid">
        {visibleOptions.map(opt => (
          <button
            key={opt}
            className={`chip ${selected.includes(opt) ? 'selected' : ''}`}
            onClick={() => toggle(opt)}
          >
            {opt}
          </button>
        ))}
      </div>

      {!showAll && filter.length === 0 && hiddenCount > 0 && (
        <button className="btn-text" onClick={() => setShowAll(true)}>
          + Show {hiddenCount} more
        </button>
      )}
      {showAll && filter.length === 0 && (
         <button className="btn-text" onClick={() => setShowAll(false)}>
          Show less
        </button>
      )}
    </div>
  );
};

const App = () => {
  const [genreOptions, setGenreOptions] = useState(INITIAL_GENRE_OPTIONS);
  const [subgenreOptions, setSubgenreOptions] = useState(INITIAL_SUBGENRE_OPTIONS);

  const [worldMusicOptions, setWorldMusicOptions] = useState(INITIAL_WORLD_MUSIC_OPTIONS);
  const [moodOptions, setMoodOptions] = useState(MOOD_OPTIONS);
  const [themeOptions, setThemeOptions] = useState(THEME_OPTIONS);

  const [genres, setGenres] = useState<string[]>([]);
  const [subgenres, setSubgenres] = useState<string[]>([]);
  const [worldMusicInfluences, setWorldMusicInfluences] = useState<string[]>([]);
  const [moods, setMoods] = useState<string[]>([]);
  const [themes, setThemes] = useState<string[]>([]);

  const [lyricLanguage, setLyricLanguage] = useState(LYRIC_LANGUAGE_OPTIONS[0]);
  const [duration, setDuration] = useState("4");
  const [songTitle, setSongTitle] = useState("");
  const [artistRef, setArtistRef] = useState("");
  const [tempo, setTempo] = useState(120);
  const [key, setKey] = useState(KEY_OPTIONS[0]);
  const [timeSignature, setTimeSignature] = useState(TIME_SIGNATURE_OPTIONS[0]);

  const [loading, setLoading] = useState(false);
  const [assistantLoading, setAssistantLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [outputBlocks, setOutputBlocks] = useState<any[]>([]);
  const [sources, setSources] = useState<string[]>([]); 

  const handleAssistantClick = async () => {
    setAssistantLoading(true);
    setError(null);
    try {
      const isSpecificSong = songTitle.trim().length > 0;

      let prompt = `Role: Professional Music Archivist & Metadata Specialist.
      User Request: "${songTitle}" by "${artistRef}".

      MANDATORY SEARCH STEPS (Use Google Search):
      1. Perform a deep search for this specific track to verify the artist and exact recording.
      2. Identify the EXACT GENRE and SUBGENRE based on Discogs, Wikipedia, or Music Journalism.
         - CRITICAL: If the song is culturally specific (e.g., "Campursari", "Dangdut Koplo", "Keroncong", "J-Pop", "Afrobeat"), you MUST use those specific terms. Do NOT generalize to just "Pop" or "World".
      3. Identify any Traditional/World Music influences (e.g., Gamelan, Tabla, Sitar) if applicable.
      4. Analyze the Lyrical Mood and Theme based on the actual song content (translate if necessary).
      5. Find the official studio BPM and Key.

      OUTPUT FORMAT (Return valid JSON only):
      {
        "genre": ["Most Accurate Primary Genre", "Secondary Genre"], 
        "subgenre": ["Specific Subgenre 1", "Specific Subgenre 2"], 
        "worldMusic": ["Specific Influence" or "None"], 
        "moods": ["Mood 1", "Mood 2", "Mood 3"], 
        "themes": ["Theme 1", "Theme 2"], 
        "tempo": Number, 
        "key": "String (e.g. C# Minor)", 
        "timeSignature": "String (e.g. 4/4)", 
        "lyricLanguage": "String", 
        "durationMinutes": Number
      }`;

      // Use gemini-3-pro-preview for better reasoning and search grounding
      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
            tools: isSpecificSong ? [{ googleSearch: {} }] : [],
            responseMimeType: "application/json",
            thinkingConfig: { thinkingBudget: 1024 } // Enable thinking to verify metadata accuracy
        },
      }));

      let text = response.text || "";
      let suggestions;
      try {
          text = text.replace(/```json/g, "").replace(/```/g, "").trim();
          const start = text.indexOf('{');
          const end = text.lastIndexOf('}');
          suggestions = JSON.parse(text.substring(start, end + 1));
      } catch (e) {
          throw new Error("Failed to parse AI suggestions.");
      }

      if (suggestions.genre) {
          const arr = Array.isArray(suggestions.genre) ? suggestions.genre : [suggestions.genre];
          setGenreOptions(prev => Array.from(new Set([...arr, ...prev]))); // Add new found genres to options
          setGenres(arr.slice(0, 3));
      }
      if (suggestions.subgenre) {
          const arr = Array.isArray(suggestions.subgenre) ? suggestions.subgenre : [suggestions.subgenre];
          setSubgenreOptions(prev => Array.from(new Set([...arr, ...prev]))); // Add new found subgenres
          setSubgenres(arr.slice(0, 3));
      }

      if (suggestions.worldMusic) {
          const arr = Array.isArray(suggestions.worldMusic) ? suggestions.worldMusic : [suggestions.worldMusic];
          setWorldMusicOptions(prev => Array.from(new Set([...arr, ...prev])));
          setWorldMusicInfluences(arr.slice(0, 5));
      }
      if (suggestions.moods) {
          const arr = Array.isArray(suggestions.moods) ? suggestions.moods : [suggestions.moods];
          setMoodOptions(prev => Array.from(new Set([...arr, ...prev])));
          setMoods(arr.slice(0, 5));
      }
      if (suggestions.themes) {
          const arr = Array.isArray(suggestions.themes) ? suggestions.themes : [suggestions.themes];
          setThemeOptions(prev => Array.from(new Set([...arr, ...prev])));
          setThemes(arr.slice(0, 5));
      }

      // Sync menu state with AI suggestions
      if (suggestions.tempo) setTempo(Math.round(Math.max(40, Math.min(220, suggestions.tempo))));
      if (suggestions.key) setKey(KEY_OPTIONS.find(k => suggestions.key.includes(k)) || KEY_OPTIONS[0]);
      if (suggestions.timeSignature && TIME_SIGNATURE_OPTIONS.includes(suggestions.timeSignature)) setTimeSignature(suggestions.timeSignature);
      if (suggestions.lyricLanguage) {
          const matchedLang = LYRIC_LANGUAGE_OPTIONS.find(l => suggestions.lyricLanguage.toLowerCase().includes(l.toLowerCase()));
          if (matchedLang) setLyricLanguage(matchedLang);
      }
      if (suggestions.durationMinutes) setDuration(suggestions.durationMinutes >= 6 ? "8" : "4");

    } catch (e) {
      setError("AI assistant failed. Please try again.");
    } finally {
      setAssistantLoading(false);
    }
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setOutputBlocks([]);
    setSources([]);

