// --- Helper for Retry Logic ---
const callWithRetry = async (apiCall: () => Promise<any>, retries = 3, baseDelay = 2000) => {
    for (let i = 0; i < retries; i++) {
        try {
            return await apiCall();
        } catch (error: any) {
             let isQuotaError = false;
             const msg = (error.message || '').toString();
             if (
                 error.status === 429 || 
                 error.status === 503 ||
                 msg.includes('429') || 
                 msg.includes('RESOURCE_EXHAUSTED') || 
                 msg.toLowerCase().includes('quota') || 
                 msg.toLowerCase().includes('rate limit')
             ) {
                 isQuotaError = true;
             }

            if (isQuotaError && i < retries - 1) {
                const delayTime = (baseDelay * Math.pow(2, i)) + (Math.random() * 1000);
                console.warn(`API Busy (Attempt ${i + 1}/${retries}). Retrying in ${Math.round(delayTime)}ms...`);
                await new Promise(resolve => setTimeout(resolve, delayTime));
                continue;
            }
            throw error;
        }
    }
};

