  const [artistRef, setArtistRef] = useState("");
  const [tempo, setTempo] = useState(120);
  const [key, setKey] = useState(KEY_OPTIONS[0]);
  const [timeSignature, setTimeSignature] = useState(TIME_SIGNATURE_OPTIONS[0]);

  const [loading, setLoading] = useState(false);
  const [assistantLoading, setAssistantLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [outputBlocks, setOutputBlocks] = useState<any[]>([]);
  const [sources, setSources] = useState<string[]>([]); 

  const applySuggestions = (suggestions: any) => {
      // Helper to sanitize arrays (ensure strings only)
      const sanitizeStringArray = (arr: any) => {
          if (!Array.isArray(arr)) return typeof arr === 'string' ? [arr] : [];
          return arr.filter(item => typeof item === 'string' && item.trim().length > 0);
      };

      if (suggestions.genre) {
          const arr = sanitizeStringArray(suggestions.genre);
          if (arr.length > 0) {
             setGenreOptions(prev => Array.from(new Set([...arr, ...prev]))); 
             setGenres(arr.slice(0, 3));
          }
      }
      if (suggestions.subgenre) {
          const arr = sanitizeStringArray(suggestions.subgenre);
          if (arr.length > 0) {
            setSubgenreOptions(prev => Array.from(new Set([...arr, ...prev]))); 
            setSubgenres(arr.slice(0, 3));
          }
      }

      if (suggestions.worldMusic) {
          const arr = sanitizeStringArray(suggestions.worldMusic);
          if (arr.length > 0) {
            setWorldMusicOptions(prev => Array.from(new Set([...arr, ...prev])));
            setWorldMusicInfluences(arr.slice(0, 5));
          }
      }
      if (suggestions.moods) {
          const arr = sanitizeStringArray(suggestions.moods);
          if (arr.length > 0) {
            setMoodOptions(prev => Array.from(new Set([...arr, ...prev])));
            setMoods(arr.slice(0, 5));
          }
      }
      if (suggestions.themes) {
          const arr = sanitizeStringArray(suggestions.themes);
          if (arr.length > 0) {
            setThemeOptions(prev => Array.from(new Set([...arr, ...prev])));
            setThemes(arr.slice(0, 5));
          }
      }

      // Sync menu state with AI suggestions
      if (suggestions.tempo) setTempo(Math.round(Math.max(40, Math.min(220, suggestions.tempo))));
      if (suggestions.key) setKey(KEY_OPTIONS.find(k => suggestions.key && suggestions.key.includes(k)) || KEY_OPTIONS[0]);
      if (suggestions.timeSignature && TIME_SIGNATURE_OPTIONS.includes(suggestions.timeSignature)) setTimeSignature(suggestions.timeSignature);
      if (suggestions.lyricLanguage) {
          const matchedLang = LYRIC_LANGUAGE_OPTIONS.find(l => suggestions.lyricLanguage.toLowerCase().includes(l.toLowerCase()));
          if (matchedLang) setLyricLanguage(matchedLang);
      }
      if (suggestions.durationMinutes) setDuration(suggestions.durationMinutes >= 6 ? "8" : "4");
  };

  const handleAssistantClick = async () => {
    setAssistantLoading(true);
    setError(null);
    try {
      const isSpecificSong = songTitle.trim().length > 0;

      const prompt = `Role: Professional Music Archivist.
      User Request: "${songTitle}" by "${artistRef}".

      MANDATORY:
      1. Verify artist/song.
      2. Identify EXACT GENRE and SUBGENRE (e.g. "Dangdut Koplo", "Keroncong", "J-Pop").
      3. Identify World Music influences.
      4. Analyze Mood/Theme.
      5. Estimate BPM/Key.

      OUTPUT FORMAT (Valid JSON only):
      {
        "genre": ["Genre1", "Genre2"], 
        "subgenre": ["Subgenre1", "Subgenre2"], 
        "worldMusic": ["Influence"], 
        "moods": ["Mood1", "Mood2"], 
        "themes": ["Theme1", "Theme2"], 
        "tempo": 120, 
        "key": "C Minor", 
        "timeSignature": "4/4", 
        "lyricLanguage": "Indonesian", 
        "durationMinutes": 4
      }`;

      try {
        // Attempt 1: PRO Model (High Accuracy, Grounded)
        // Note: Do NOT use responseMimeType when using tools to avoid conflicts.
        const response = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: { 
                tools: isSpecificSong ? [{ googleSearch: {} }] : [],
                thinkingConfig: { thinkingBudget: 512 } 
            },
        }), 1); // Fail fast (1 retry) to switch to fallback

        const suggestions = extractJSON(response.text || "");
        if (suggestions) {
            applySuggestions(suggestions);
            return; // Success, exit
        }
        throw new Error("Pro model returned invalid JSON");

      } catch (proError) {
        console.warn("Pro model failed or timed out. Switching to Flash model...", proError);

        // Attempt 2: FLASH Model (High Speed, Fallback)
        // Uses responseMimeType: "application/json" for reliability since we drop tools here for speed/stability
        const response = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-2.5-flash-latest', 
            contents: prompt + " Note: Provide best guess based on title/artist.",
            config: { 
                responseMimeType: "application/json"
            },
        }));

        const suggestions = extractJSON(response.text || "");
        if (suggestions) {
            applySuggestions(suggestions);
        } else {
            throw new Error("Flash model also failed to return JSON.");
        }
      }

    } catch (e) {
      setError("Auto-fill failed. Please enter details manually.");
    } finally {
      setAssistantLoading(false);
    }
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setOutputBlocks([]);
    setSources([]);

    const isSpecificSong = songTitle.trim().length > 0;

    // Convert arrays to comma-separated strings for the prompt
    const genreStr = genres.join(", ") || "General";
    const subgenreStr = subgenres.join(", ") || "General";
    const moodStr = moods.join(", ") || "Varied";
    const themeStr = themes.join(", ") || "General";
    const worldStr = worldMusicInfluences.join(", ") || "None";

    const prompt = `ACT AS A WORLD-CLASS MUSIC PRODUCER.
    Target: "${songTitle}" (Style: "${artistRef}")
    User Input Context: Genre [${genreStr}], Moods [${moodStr}], User Input Tempo: [${tempo} BPM].

    MANDATE:
    1. SYNCHRONIZATION: Use Google Search to find if "${songTitle}" exists. 
       **CRITICAL FOR EXISTING SONGS**: 
       - Retrieve the EXACT lyrics and the EXACT song structure.
       - You MUST place the specific lyrics into their CORRECT structural sections.
       - Use REAL STUDIO BPM/KEY (OVERRIDE user input).
    2. IF NEW SONG: Use user input to create a creative structure.
    3. METADATA LAYERS: Generate detailed: [STRUCTURE], [MELODIC ELEMENTS], [HARMONIC ELEMENTS], [RHYTHMIC ELEMENTS], [INSTRUMENTATION].
    4. CHORD VOCABULARY: Use specific chords (e.g., [A5] for Rock, [Cmaj7] for Jazz).
    5. LEAD SHEET FORMATTING: Chords MUST be placed EXACTLY above the syllable.
    6. ARRANGEMENT (CRITICAL):
       - Inside [LYRICS & ARRANGEMENT], every section MUST have:
         [Instrumentation: ...]
         [Vocals: ...]
         [SFX: ...]  <-- THIS IS REQUIRED FOR EVERY SECTION.
       - The [SFX] tag must describe sound effects relevant to that specific part of the song (e.g. "Reverse cymbal", "Rain", "Explosion").

    STRICT FORMAT TEMPLATE (Follow this Pattern):
    [Title: ${songTitle}]
    [Artist: ${artistRef}]
    [Genre: ${genreStr}]
    [Subgenre: ${subgenreStr}]
    [World Music: ${worldStr}]
    [Moods: ${moodStr}]
    [Themes: ${themeStr}]
    [Tempo: (INSERT ACTUAL DETECTED BPM HERE) BPM]
    [Key: ${key}]
    [Time Signature: ${timeSignature}]
    [Duration: ${duration === "4" ? "~4 min" : "~8 min"}]
    [Language: ${lyricLanguage}]

    [STRUCTURE]
    [Intro: ... bars]
    [Verse 1: ... lines]
    ...

    [MELODIC ELEMENTS]
    ...

    [HARMONIC ELEMENTS]
    ...

    [RHYTHMIC ELEMENTS]
    ...

    [INSTRUMENTATION]
    ...

    [LYRICS & ARRANGEMENT]
    [Verse 1]
    [Instrumentation: Lo-fi piano loops, dusty vinyl crackle, deep sub bass]
    [Vocals: Whisper-rap, intimate, close-mic]
    [SFX: Distant sirens, rain texture]
    [Am9]           [Em7]
    Lyrics text here...

    [Chorus]
    [Instrumentation: Wall of sound guitars, crashing cymbals, synth lead]
    [Vocals: Layered harmonies, anthemic shouting]
    [SFX: White noise risers, explosion impact]
    [C5]            [G5]
    Lyrics text here...

    [Bridge]
    [Instrumentation: Minimalist, stripped back]
    [Vocals: Raw, emotional, cracking voice]
    [SFX: Heartbeat thud, tape stop effect]
    [Dm]            [Am/C]
    Lyrics text here...

    [STYLE_DESCRIPTION_SECTION]
    (Description)`;

    const systemInstruction = `You are an expert Music Arranger.
    RULES:
    1. **MAX LENGTH**: Keep output concise (under 5000 chars).
    2. **FORMATTING**: 
       - Metadata keys in [Square Brackets].
       - **CRITICAL**: The [SFX] tag is MANDATORY for every single song section in the lyrics block.
    3. **ACCURACY**: For known songs, use exact lyrics and structure.
    4. **CHORDS**: Align chords precisely over lyrics.`;

    try {
      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{googleSearch: {}}],
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192,
          systemInstruction: systemInstruction,
        },
      }));

      const responseText = response.text ? response.text.trim() : "";

      // --- SYNC UI STATE WITH RESULT (Menu Synchronization) ---
      try {
        const tempoMatch = responseText.match(/\[Tempo:\s*(\d+)\s*BPM\]/i);
        if (tempoMatch && tempoMatch[1]) {
           const parsedTempo = parseInt(tempoMatch[1]);
           if (!isNaN(parsedTempo) && parsedTempo >= 40 && parsedTempo <= 220) {
               setTempo(parsedTempo); // This syncs the slider
           }
        }

        const keyMatch = responseText.match(/\[Key:\s*([^\]]+)\]/i);
        if (keyMatch && keyMatch[1]) {
           const parsedKey = keyMatch[1].trim();
           const validKey = KEY_OPTIONS.find(k => k.toLowerCase() === parsedKey.toLowerCase());
           if (validKey) setKey(validKey); // This syncs the dropdown
        }
      } catch (syncError) {
        console.warn("Failed to sync menu with result:", syncError);
      }
      // -----------------------------------------------------

      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
          const chunks = response.candidates[0].groundingMetadata.groundingChunks;
          const uniqueSources = Array.from(new Set(chunks.map((chunk: any) => chunk.web?.uri).filter(u => u))) as string[];
          setSources(uniqueSources);
      }

      const summaryMarker = '[STYLE_DESCRIPTION_SECTION]';
      const summaryIndex = responseText.lastIndexOf(summaryMarker);

      if (summaryIndex !== -1) {
        setOutputBlocks([
          { title: "Generated Music Template", content: responseText.substring(0, summaryIndex).trim() },
          { title: "Style Description", content: responseText.substring(summaryIndex + summaryMarker.length).trim() },
        ]);
      } else {
        // Fallback if marker is missing: still display the text.
        setOutputBlocks([{ title: "Generated Music Template", content: responseText }]);
      }
    } catch (e) {
      setError("Failed to generate template. Quota reached or API error.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container">
      <header>
        <h1>Warga Digital Studio</h1>
        <div className="promo-banner">
          <p>Create & Distribute Your Music</p>
        </div>
      </header>

      <main className="main-content">
        <section className="controls">
          <h2>Configuration</h2>
          <div className="form-group">
            <label>Song Title</label>
            <input type="text" value={songTitle} onChange={(e) => setSongTitle(e.target.value)} placeholder="e.g. Dawai Asmara" />
          </div>
          <div className="form-group">
            <label>Artist Style</label>
            <input type="text" value={artistRef} onChange={(e) => setArtistRef(e.target.value)} placeholder="e.g. Waldjinah" />
          </div>
          <button className="btn btn-secondary btn-full-width" onClick={handleAssistantClick} disabled={assistantLoading}>
            {assistantLoading ? <div className="spinner small"></div> : "Auto-Fill Suggestions"}
          </button>

          <MultiSelect 
            label="Genre (Select up to 3)" 
            options={genreOptions} 
            selected={genres} 
            onChange={setGenres} 
            max={3} 
          />

          <MultiSelect 
            label="Subgenre (Select up to 3)" 
            options={subgenreOptions} 
            selected={subgenres} 
            onChange={setSubgenres} 
            max={3} 
          />

          {/* Multi-Select Components */}
          <MultiSelect 
            label="Mood (Select up to 5)" 
            options={moodOptions} 
            selected={moods} 
            onChange={setMoods} 
            max={5} 
          />

          <MultiSelect 
            label="Theme (Select up to 5)" 
            options={themeOptions} 
            selected={themes} 
            onChange={setThemes} 
            max={5} 
          />

          <MultiSelect 
            label="World Music Influence (Select up to 5)" 
            options={worldMusicOptions} 
            selected={worldMusicInfluences} 
            onChange={setWorldMusicInfluences} 
            max={5} 
          />

          <div className="form-group">
            <label>Tempo (BPM): {tempo}</label>
            <input type="range" min="40" max="220" value={tempo} onChange={(e) => setTempo(parseInt(e.target.value))} />
          </div>

           <div className="form-group">
            <label>Key</label>
            <select value={key} onChange={(e) => setKey(e.target.value)}>
              {KEY_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Time Signature</label>
            <select value={timeSignature} onChange={(e) => setTimeSignature(e.target.value)}>
              {TIME_SIGNATURE_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>

          <div className="form-group">
            <label>Lyric Language</label>
            <select value={lyricLanguage} onChange={(e) => setLyricLanguage(e.target.value)}>
              {LYRIC_LANGUAGE_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
           <div className="form-group">
            <label>Duration</label>
            <div style={{display: 'flex', gap: '1rem', marginTop: '0.5rem'}}>
                <label style={{cursor: 'pointer', display: 'flex', alignItems: 'center'}}>
                    <input type="radio" value="4" checked={duration === "4"} onChange={(e) => setDuration(e.target.value)} style={{marginRight: '0.5rem', width: 'auto'}} /> ~4 min
                </label>
                <label style={{cursor: 'pointer', display: 'flex', alignItems: 'center'}}>
                    <input type="radio" value="8" checked={duration === "8"} onChange={(e) => setDuration(e.target.value)} style={{marginRight: '0.5rem', width: 'auto'}} /> ~8 min
                </label>
            </div>
          </div>

          <button className="btn btn-primary btn-full-width" onClick={handleGenerate} disabled={loading} style={{marginTop: '1.5rem'}}>
            {loading ? <div className="spinner small"></div> : "Generate Full Lyrics & Structure"}
          </button>
        </section>

        <section className="output">
          {error && <div className="error-message">{error}</div>}
          {loading && <div className="spinner-wrapper"><div className="spinner"></div><p>Searching for official lyrics and composing arrangement...</p></div>}
          {assistantLoading && <div className="spinner-wrapper"><div className="spinner small"></div><p>Scanning global music databases & detecting style...</p></div>}

          {outputBlocks.length > 0 && (
            <div className="output-blocks-wrapper">
                {outputBlocks.map((block, i) => (
                    <div key={i} className="output-block">
                        <h3>{block.title}</h3>
                        <button className="btn-copy" onClick={() => navigator.clipboard.writeText(block.content)}>Copy</button>
                        <pre>{block.content}</pre>
                        {i === 0 && sources.length > 0 && (
                          <div className="info-text" style={{textAlign: 'left', borderTop: '1px solid #333', marginTop: '1rem', paddingTop: '1rem'}}>
                            <strong>Lyric Sources Used:</strong>
                            <ul>{sources.map((s, j) => <li key={j}><a href={s} target="_blank" rel="noopener noreferrer">{s}</a></li>)}</ul>
                          </div>
                        )}
                    </div>
                ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
};

