        "moods": ["Mood 1", "Mood 2", "Mood 3"], 
        "themes": ["Theme 1", "Theme 2"], 
        "tempo": 120, 
        "key": "C Minor", 
        "timeSignature": "4/4", 
        "lyricLanguage": "Indonesian", 
        "durationMinutes": 4
      }`;

      // Strictly using gemini-3-pro-preview with increased thinking budget for deep search
      const response = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: { 
                tools: isSpecificSong ? [{ googleSearch: {} }] : [],
                thinkingConfig: { thinkingBudget: 2048 }, // Increased for research
                responseMimeType: "application/json" // Enforce JSON for the suggestion part
            },
      }));

      const suggestions = extractJSON(response.text || "");
      if (suggestions) {
          applySuggestions(suggestions);
      } else {
          throw new Error("Could not interpret AI response. Please try again.");
      }

    } catch (e: any) {
      console.error(e);
      setError("Assistant is busy or failed to find data. Please enter manually.");
    } finally {
      setAssistantLoading(false);
    }
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setOutputBlocks([]);
    setSources([]);

    // Formatting for Prompt
    const genreStr = genres.join(", ") || "General";
    const subgenreStr = subgenres.join(", ") || "General";
    const moodStr = moods.join(", ") || "Varied";
    const themeStr = themes.join(", ") || "General";
    const worldStr = worldMusicInfluences.join(", ") || "None";

    const prompt = `ACT AS A WORLD-CLASS MUSIC PRODUCER.
    Target: "${songTitle}" (Style: "${artistRef}")
    Context: Genre [${genreStr}], Moods [${moodStr}], Tempo [${tempo} BPM].

    MANDATE:
    1. SYNCHRONIZATION: Use Google Search to find if "${songTitle}" exists. 
       **CRITICAL**: If existing song, retrieve EXACT lyrics and structure. Use REAL STUDIO BPM/KEY.
    2. METADATA LAYERS: Fill the STRICT TEMPLATE below.
    3. LYRICS & ARRANGEMENT Rules:
       - **NO CHORDS** inside the lyrics block. (Chords go in [Harmonic Elements] only).
       - **TAG ORDER** for every section:
         [Instrumentation: ...]
         [SFX: ...]  <-- MUST BE ABOVE VOCALS
         [Vocals: ...]
       - Then the lyrics.

    STRICT FORMAT TEMPLATE:
    [title: ${songTitle}]
    [genre: ${genreStr}]
    [subgenre: ${subgenreStr}]
    [world music influence: ${worldStr}]
    [tempo: (DETECTED) BPM]
    [key: ${key}]
    [time signature: ${timeSignature}]
    [duration: ${duration === "4" ? "4:00" : "8:00"}]
    [language: ${lyricLanguage}]

    [primary emotion: e.g. (Analyze)]
    [secondary emotion: e.g. (Analyze)]
    [mood: ${moodStr}]

    [theme: ${themeStr}]
    [narrative style: e.g. (Analyze)]
    [rhyme scheme: e.g. (Analyze)]
    [metaphor: e.g. (Analyze)]
    [hook/tagline: e.g. (Identify)]

    [structure]
    (List sections with bar counts, e.g., [intro: 8 bars])

    [melodic elements]
    [verse melody: description]
    [chorus melody: description]
    [bridge melody: description]
    [key change: Yes/No]

    [harmonic elements]
    [chord progression (verse): e.g. Em - D - C - Bm]
    [chord progression (chorus): e.g. G - D - Em - C]

    [rhythmic elements]
    [rhythmic feel: description]
    [drum pattern: description]
    [notable rhythmic features: description]

    [instrumentation]
    [lead instrument: description]
    [rhythm section: description]
    [additional instruments: description]
    [production elements: description]

    [dynamic instructions]
    [verse dynamic: description]
    [chorus dynamic: description]
    [dynamic changes: description]

    [special instructions]
    [unique features: description]
    [cultural references: description]
    [target audience: description]
    [inspiration: ${artistRef}]

    [ai-specific guidelines]
    [lyrical style: description]
    [rhyme density: description]
    [metaphor usage: description]
    [repetition: description]
    [emotional progression: description]
    [language complexity: description]

    [lyrics & arrangement]
    [Verse 1]
    [Instrumentation: description]
    [SFX: description]
    [Vocals: description]
    (Lyrics text here...)

    [Chorus]
    [Instrumentation: description]
    [SFX: description]
    [Vocals: description]
    (Lyrics text here...)

    ... and so on.

    [STYLE_DESCRIPTION_SECTION]
    (Short description)`;

    const systemInstruction = `You are an expert Music Arranger.
    RULES:
    1. **ACCURACY**: For known songs, use exact lyrics/structure.
    2. **SFX TAG**: REQUIRED for every section in lyrics.
    3. **NO CHORDS IN LYRICS**: Keep the lyrics block clean.`;

    try {
      // Strictly using gemini-3-pro-preview
      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{googleSearch: {}}],
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192,
          systemInstruction: systemInstruction,
        },
      }));

      const responseText = response.text ? response.text.trim() : "";

      // Update sources if available
      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
          const chunks = response.candidates[0].groundingMetadata.groundingChunks;
          const uniqueSources = Array.from(new Set(chunks.map((chunk: any) => chunk.web?.uri).filter((u: any) => u))) as string[];
          setSources(uniqueSources);
      }

      const summaryMarker = '[STYLE_DESCRIPTION_SECTION]';
      const summaryIndex = responseText.lastIndexOf(summaryMarker);

      if (summaryIndex !== -1) {
        setOutputBlocks([
          { title: "Generated Music Template", content: responseText.substring(0, summaryIndex).trim() },
          { title: "Style Description", content: responseText.substring(summaryIndex + summaryMarker.length).trim() },
        ]);
      } else {
        setOutputBlocks([{ title: "Generated Music Template", content: responseText }]);
      }

    } catch (e: any) {
      console.error(e);
      setError(`Generation failed: ${e.message || "Unknown error"}. Please try again.`);
    } finally {
      setLoading(false);
    }
  };

