  const applySuggestions = (suggestions: any) => {
      const sanitize = (arr: any) => {
          if (!Array.isArray(arr)) return typeof arr === 'string' ? [arr] : [];
          return arr.filter(item => typeof item === 'string' && item.trim().length > 0);
      };

      // Helper to add unique items to options and select them
      const updateSelection = (
          newItems: string[], 
          currentOptions: string[], 
          setOptions: React.Dispatch<React.SetStateAction<string[]>>, 
          setSelected: React.Dispatch<React.SetStateAction<string[]>>,
          limit: number
      ) => {
          if (newItems.length > 0) {
              setOptions(prev => Array.from(new Set([...newItems, ...prev]))); 
              setSelected(newItems.slice(0, limit));
          }
      };

      if (suggestions.genre) updateSelection(sanitize(suggestions.genre), genreOptions, setGenreOptions, setGenres, 3);
      if (suggestions.subgenre) updateSelection(sanitize(suggestions.subgenre), subgenreOptions, setSubgenreOptions, setSubgenres, 3);
      if (suggestions.worldMusic) updateSelection(sanitize(suggestions.worldMusic), worldMusicOptions, setWorldMusicOptions, setWorldMusicInfluences, 5);
      if (suggestions.moods) updateSelection(sanitize(suggestions.moods), moodOptions, setMoodOptions, setMoods, 5);
      if (suggestions.themes) updateSelection(sanitize(suggestions.themes), themeOptions, setThemeOptions, setThemes, 5);

      if (suggestions.tempo) {
          const t = parseInt(suggestions.tempo);
          if (!isNaN(t) && t >= 40 && t <= 220) setTempo(t);
      }
      if (suggestions.key) {
          const k = KEY_OPTIONS.find(opt => suggestions.key.includes(opt));
          if (k) setKey(k);
      }
      if (suggestions.timeSignature && TIME_SIGNATURE_OPTIONS.includes(suggestions.timeSignature)) {
          setTimeSignature(suggestions.timeSignature);
      }
      if (suggestions.lyricLanguage) {
          const l = LYRIC_LANGUAGE_OPTIONS.find(opt => suggestions.lyricLanguage.toLowerCase().includes(opt.toLowerCase()));
          if (l) setLyricLanguage(l);
      }
      if (suggestions.durationMinutes) {
          setDuration(suggestions.durationMinutes >= 6 ? "8" : "4");
      }
  };

