        "timeSignature": "4/4", 
        "lyricLanguage": "Indonesian", 
        "durationMinutes": 5
      }`;

      // Strictly using gemini-3-pro-preview with increased thinking budget for deep search
      const response = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: { 
                tools: isSpecificSong ? [{ googleSearch: {} }] : [],
                thinkingConfig: { thinkingBudget: 2048 }, // Increased for research
                responseMimeType: "application/json" // Enforce JSON for the suggestion part
