  const [moods, setMoods] = useState<string[]>([]);
  const [themes, setThemes] = useState<string[]>([]);

  const [lyricLanguage, setLyricLanguage] = useState(LYRIC_LANGUAGE_OPTIONS[0]);
  const [duration, setDuration] = useState("4");
  const [songTitle, setSongTitle] = useState("");
  const [artistRef, setArtistRef] = useState("");
  const [tempo, setTempo] = useState(120);
  const [key, setKey] = useState(KEY_OPTIONS[0]);
  const [timeSignature, setTimeSignature] = useState(TIME_SIGNATURE_OPTIONS[0]);

  const [loading, setLoading] = useState(false);
  const [assistantLoading, setAssistantLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [outputBlocks, setOutputBlocks] = useState<any[]>([]);
  const [sources, setSources] = useState<string[]>([]); 

  // --- Helper to safely update state from AI suggestions ---
  const applySuggestions = (suggestions: any) => {
      const sanitize = (arr: any) => {
          if (!Array.isArray(arr)) return typeof arr === 'string' ? [arr] : [];
          return arr.filter(item => typeof item === 'string' && item.trim().length > 0);
      };

      // Helper to add unique items to options and select them without limits
      const updateSelection = (
          newItems: string[], 
          currentOptions: string[], 
          setOptions: React.Dispatch<React.SetStateAction<string[]>>, 
          setSelected: React.Dispatch<React.SetStateAction<string[]>>
      ) => {
          if (newItems.length > 0) {
              setOptions(prev => Array.from(new Set([...newItems, ...prev]))); 
              // UNLIMITED SELECTION: Removed slicing to allow full AI suggestion set
              setSelected(newItems);
          }
      };

      if (suggestions.genre) updateSelection(sanitize(suggestions.genre), genreOptions, setGenreOptions, setGenres);
      if (suggestions.subgenre) updateSelection(sanitize(suggestions.subgenre), subgenreOptions, setSubgenreOptions, setSubgenres);
      if (suggestions.worldMusic) updateSelection(sanitize(suggestions.worldMusic), worldMusicOptions, setWorldMusicOptions, setWorldMusicInfluences);
      if (suggestions.moods) updateSelection(sanitize(suggestions.moods), moodOptions, setMoodOptions, setMoods);
      if (suggestions.themes) updateSelection(sanitize(suggestions.themes), themeOptions, setThemeOptions, setThemes);

      if (suggestions.tempo) {
          const t = parseInt(suggestions.tempo);
          if (!isNaN(t) && t >= 40 && t <= 220) setTempo(t);
      }
      if (suggestions.key) {
          const k = KEY_OPTIONS.find(opt => suggestions.key.includes(opt));
          if (k) setKey(k);
      }
      if (suggestions.timeSignature && TIME_SIGNATURE_OPTIONS.includes(suggestions.timeSignature)) {
          setTimeSignature(suggestions.timeSignature);
      }
      if (suggestions.lyricLanguage) {
          const l = LYRIC_LANGUAGE_OPTIONS.find(opt => suggestions.lyricLanguage.toLowerCase().includes(opt.toLowerCase()));
          if (l) setLyricLanguage(l);
      }
      if (suggestions.durationMinutes) {
          setDuration(suggestions.durationMinutes >= 6 ? "8" : "4");
      }
  };

  const handleAssistantClick = async () => {
    setAssistantLoading(true);
    setError(null);
    try {
      const isSpecificSong = songTitle.trim().length > 0;

      const prompt = `Role: Elite Music Forensic Analyst.
      Target: Analyze metadata for the song "${songTitle}" by artist "${artistRef}".

      CRITICAL CONTEXT AWARENESS:
      1. **STANDARD TERMINOLOGY ONLY**: Use STANDARD INTERNATIONAL MUSIC GENRES (e.g. AllMusic/Discogs taxonomy). 
         - **INCORRECT**: "Indonesian Rock", "Indonesian Pop".
         - **CORRECT**: Genre="Rock", Subgenre="Heavy Metal", World Music="Indonesian Rock Style".
      2. **NAME AMBIGUITY**: If the Artist Name looks like a genre (e.g., "Power Metal"), verify if it is a specific BAND (e.g., the Indonesian band "Power Metal"). 
      3. **DEEP FUSION ANALYSIS**: Identify Neoclassical, Jazz, or Symphonic elements.
      4. **EXACT BPM/KEY**: Search for "[Song Title] [Artist] BPM Key".

      OUTPUT JSON (Strict):
      {
        "genre": ["Standard Genre 1", "Standard Genre 2"], 
        "subgenre": ["Standard Subgenre 1", "Standard Subgenre 2"], 
        "worldMusic": ["Regional Style", "Traditional Instrument"], 
        "moods": ["Mood 1", "Mood 2"], 
        "themes": ["Theme 1"], 
        "tempo": 203, 
        "key": "A Minor", 
        "timeSignature": "4/4", 
        "lyricLanguage": "Indonesian", 
        "durationMinutes": 5
      }`;

      // Strictly using gemini-3-pro-preview with increased thinking budget for deep search
      const response = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: { 
                tools: isSpecificSong ? [{ googleSearch: {} }] : [],
                thinkingConfig: { thinkingBudget: 2048 }, // Increased for research
                responseMimeType: "application/json" // Enforce JSON for the suggestion part
            },
      }));

      const suggestions = extractJSON(response.text || "");
      if (suggestions) {
          applySuggestions(suggestions);
      } else {
          throw new Error("Could not interpret AI response. Please try again.");
      }

    } catch (e: any) {
      console.error(e);
      setError("Assistant is busy or failed to find data. Please enter manually.");
    } finally {
      setAssistantLoading(false);
    }
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setOutputBlocks([]);
    setSources([]);

    // Formatting for Prompt
    const genreStr = genres.join(", ") || "General";
    const subgenreStr = subgenres.join(", ") || "General";
    const moodStr = moods.join(", ") || "Varied";
    const themeStr = themes.join(", ") || "General";
    const worldStr = worldMusicInfluences.join(", ") || "None";

    const prompt = `ACT AS A WORLD-CLASS MUSIC PRODUCER & LYRICIST ARCHIVIST.
    Target: "${songTitle}" (Style: "${artistRef}")
    Context: Genre [${genreStr}], Moods [${moodStr}], Tempo [${tempo} BPM].

    **CRITICAL MISSION - ORIGINALITY & FORMAT**:
    1. **NO PREAMBLE/POSTSCRIPT**: Output ONLY the structured text starting with "[title: ...]".
    2. **VERIFICATION**: Use Google Search to find the OFFICIAL lyrics and structure for "${songTitle}" by "${artistRef}".
    3. **EXACT LYRICS**: You must output the **EXACT, WORD-FOR-WORD** lyrics from the original song.
    4. **TRUE STRUCTURE**: Follow the song's original structure exactly.
    5. **TERMINOLOGY**: Ensure [genre] and [subgenre] fields use Standard International Terminology (e.g., Rock, Heavy Metal). Use [cultural references] or [world music influence] for regional tags (e.g., Indonesian Rock).
    6. **TECHNICAL VOCAL & SFX ACCURACY**:
       - **[Vocals]**: Use specific technical terms (e.g., *Falsetto, Belting, Vocal Fry, Growl, Vibrato, Melisma, Sprechgesang, Staccato, Legato, Harmonies (3rd/5th), Unison, Call & Response*). Avoid vague terms like "high singing".
       - **[SFX]**: Use standard audio production terms (e.g., *Reverb Tail, Delay Throw, Filter Sweep, Riser, Sub Drop, Vinyl Crackle, Tape Stop, Distortion, Flanger, Reverse Reverb, EQ Filter, White Noise*).

    METADATA LAYERS: Fill the STRICT TEMPLATE below.

    LYRICS & ARRANGEMENT Rules:
       - **NO CHORDS** inside the lyrics block. (Chords go in [Harmonic Elements] only).
       - **TAG ORDER** for every section:
         [Instrumentation: ...]
         [SFX: ...]  <-- MUST BE ABOVE VOCALS. Use professional audio terms.
         [Vocals: ...] <-- Use professional vocal technique terms.
       - Then the lyrics.

    STRICT FORMAT TEMPLATE (START OUTPUT HERE):
    [title: ${songTitle}]
    [genre: ${genreStr}]
    [subgenre: ${subgenreStr}]
    [world music influence: ${worldStr}]
    [tempo: (DETECTED) BPM]
    [key: ${key}]
    [time signature: ${timeSignature}]
    [duration: ${duration === "4" ? "4:00" : "8:00"}]
    [language: ${lyricLanguage}]

    [primary emotion: e.g. (Analyze)]
    [secondary emotion: e.g. (Analyze)]
    [mood: ${moodStr}]

    [theme: ${themeStr}]
    [narrative style: e.g. (Analyze)]
    [rhyme scheme: e.g. (Analyze)]
    [metaphor: e.g. (Analyze)]
    [hook/tagline: e.g. (Identify)]

    [structure]
    (List sections with bar counts based on the REAL SONG, e.g., [intro: 8 bars])

    [melodic elements]
    [verse melody: description]
    [chorus melody: description]
    [bridge melody: description]
    [key change: Yes/No]

    [harmonic elements]
    [chord progression (verse): e.g. Em - D - C - Bm]
    [chord progression (chorus): e.g. G - D - Em - C]

    [rhythmic elements]
    [rhythmic feel: description]
    [drum pattern: description]
    [notable rhythmic features: description]

    [instrumentation]
    [lead instrument: description]
    [rhythm section: description]
    [additional instruments: description]
    [production elements: description]

    [dynamic instructions]
    [verse dynamic: description]
    [chorus dynamic: description]
    [dynamic changes: description]

    [special instructions]
    [unique features: description]
    [cultural references: description]
    [target audience: description]
    [inspiration: ${artistRef}]

    [ai-specific guidelines]
    [lyrical style: description]
    [rhyme density: description]
    [metaphor usage: description]
    [repetition: description]
    [emotional progression: description]
    [language complexity: description]

    [lyrics & arrangement]
    (Generate the sections below dynamically based on the REAL SONG structure found via Search. Do not default to Verse 1/Verse 2 if the song is different.)

    [Section Name]
    [Instrumentation: description]
    [SFX: Professional Term (e.g., Reverb Tail, Delay Throw)]
    [Vocals: Professional Technique (e.g., Belting, Falsetto)]
    (Exact Lyrics Lines...)

    ... and so on for all sections.

    [STYLE_DESCRIPTION_SECTION]
    (Short description)`;

    const systemInstruction = `You are an expert Music Archivist and Audio Engineer.
    RULES:
    1. **NO CONVERSATION**: Output ONLY the requested format.
    2. **LYRIC INTEGRITY**: The lyrics MUST be identical to the original recording.
    3. **STRUCTURAL INTEGRITY**: Respect the song's original flow.
    4. **TECHNICAL VOCABULARY**: Use professional audio engineering and music theory terms for [Vocals] (e.g. Belting, Vibrato) and [SFX] (e.g. Reverb, Delay).
    5. **NO CHORDS IN LYRICS**.
    6. **STANDARD TAXONOMY**: Use standard music genres/subgenres only.`;

    try {
      // Strictly using gemini-3-pro-preview
      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{googleSearch: {}}],
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192,
          systemInstruction: systemInstruction,
        },
      }));

      let responseText = response.text ? response.text.trim() : "";

      // POST-PROCESSING: Remove potential conversational intro
      const startMarker = "[title:";
      const startIndex = responseText.toLowerCase().indexOf(startMarker.toLowerCase());
      if (startIndex > 0) {
        responseText = responseText.substring(startIndex);
      }

      // Update sources if available
      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
          const chunks = response.candidates[0].groundingMetadata.groundingChunks;
          const uniqueSources = Array.from(new Set(chunks.map((chunk: any) => chunk.web?.uri).filter((u: any) => u))) as string[];
          setSources(uniqueSources);
      }

      const summaryMarker = '[STYLE_DESCRIPTION_SECTION]';
      const summaryIndex = responseText.lastIndexOf(summaryMarker);

      if (summaryIndex !== -1) {
        setOutputBlocks([
          { title: "Generated Music Template", content: responseText.substring(0, summaryIndex).trim() },
          { title: "Style Description", content: responseText.substring(summaryIndex + summaryMarker.length).trim() },
        ]);
      } else {
        setOutputBlocks([{ title: "Generated Music Template", content: responseText }]);
      }

    } catch (e: any) {
      console.error(e);
      setError(`Generation failed: ${e.message || "Unknown error"}. Please try again.`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container">
