      // Strictly using gemini-3-pro-preview
      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{googleSearch: {}}],
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192,
          systemInstruction: systemInstruction,
        },
      }));

      let responseText = response.text ? response.text.trim() : "";

      // POST-PROCESSING: Remove potential conversational intro
      const startMarker = "[title:";
      const startIndex = responseText.toLowerCase().indexOf(startMarker.toLowerCase());
      if (startIndex > 0) {
        responseText = responseText.substring(startIndex);
      }

      // Update sources if available
      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
          const chunks = response.candidates[0].groundingMetadata.groundingChunks;
          const uniqueSources = Array.from(new Set(chunks.map((chunk: any) => chunk.web?.uri).filter((u: any) => u))) as string[];
          setSources(uniqueSources);
      }

      const summaryMarker = '[STYLE_DESCRIPTION_SECTION]';
      const summaryIndex = responseText.lastIndexOf(summaryMarker);

      if (summaryIndex !== -1) {
        setOutputBlocks([
          { title: "Generated Music Template", content: responseText.substring(0, summaryIndex).trim() },
          { title: "Style Description", content: responseText.substring(summaryIndex + summaryMarker.length).trim() },
        ]);
      } else {
        setOutputBlocks([{ title: "Generated Music Template", content: responseText }]);
      }

    } catch (e: any) {
      console.error(e);
      setError(`Generation failed: ${e.message || "Unknown error"}. Please try again.`);
    } finally {
      setLoading(false);
    }
  };

