      const combined = [...new Set([...options, ...selected])].sort();
      return combined.filter(opt => typeof opt === 'string' && opt.trim().length > 0);
  }, [options, selected]);

  const toggle = (opt: string) => {
    if (!opt) return;
    if (selected.includes(opt)) {
      onChange(selected.filter(s => s !== opt));
