// --- Helper: Robust JSON Extractor ---
const extractJSON = (text: string) => {
  try {
    if (!text) return null;
    // Regex to capture the first valid JSON object structure
    const match = text.match(/(\{[\s\S]*\})/);
    if (match && match[0]) {
      return JSON.parse(match[0]);
    }
    return null;
  } catch (e) {
    console.warn("JSON Extraction Failed:", e);
    return null;
  }
};

// --- Helper for Retry Logic (Exponential Backoff) ---
const callWithRetry = async (apiCall: () => Promise<any>, retries = 3, baseDelay = 2000) => {
    for (let i = 0; i < retries; i++) {
        try {
            return await apiCall();
        } catch (error: any) {
             console.warn(`API call failed (Attempt ${i + 1}/${retries}):`, error.message);
             // Check for 503 (Service Unavailable) or 429 (Too Many Requests)
             if (i < retries - 1) {
                const delay = baseDelay * Math.pow(2, i) + (Math.random() * 500);
                await new Promise(resolve => setTimeout(resolve, delay));
                continue;
             }
             throw error;
        }
    }
};

// --- Custom Hook for Local Storage Persistence ---
function useLocalStorage<T>(key: string, initialValue: T) {
  // State to store our value
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === "undefined") {
      return initialValue;
    }
    try {
      // Get from local storage by key
      const item = window.localStorage.getItem(key);
      // Parse stored json or if none return initialValue
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.warn(`Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  // Return a wrapped version of useState's setter function that ...
  // ... persists the new value to localStorage.
  const setValue = (value: T | ((val: T) => T)) => {
    try {
      // Allow value to be a function so we have same API as useState
      const valueToStore =
        value instanceof Function ? value(storedValue) : value;
      // Save state
      setStoredValue(valueToStore);
      // Save to local storage
      if (typeof window !== "undefined") {
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      }
    } catch (error) {
      console.warn(`Error setting localStorage key "${key}":`, error);
    }
  };
  return [storedValue, setValue] as const;
}

