    }
  };

  // --- Helper to safely update state from AI suggestions ---
  const applySuggestions = (suggestions: any) => {
      const sanitize = (arr: any) => {
          if (!Array.isArray(arr)) return typeof arr === 'string' ? [arr] : [];
          return arr.filter(item => typeof item === 'string' && item.trim().length > 0);
      };

      // Helper to DYNAMICALLY add new unique items to options and select them
      const updateSelection = (
          newItems: string[], 
          currentOptions: string[], 
          setOptions: (val: string[]) => void, 
          setSelected: (val: string[]) => void
      ) => {
          if (newItems.length > 0) {
              // SYNCHRONIZATION FIX: Combine existing options with new AI findings
              // This ensures highly specific experimental genres found by AI are not filtered out
              const combinedOptions = Array.from(new Set([...currentOptions, ...newItems])).sort();
              setOptions(combinedOptions); 
              setSelected(newItems);
          }
      };

      if (suggestions.genre) updateSelection(sanitize(suggestions.genre), genreOptions, setGenreOptions, setGenres);
      if (suggestions.subgenre) updateSelection(sanitize(suggestions.subgenre), subgenreOptions, setSubgenreOptions, setSubgenres);
      if (suggestions.worldMusic) updateSelection(sanitize(suggestions.worldMusic), worldMusicOptions, setWorldMusicOptions, setWorldMusicInfluences);
      if (suggestions.moods) updateSelection(sanitize(suggestions.moods), moodOptions, setMoodOptions, setMoods);
      if (suggestions.themes) updateSelection(sanitize(suggestions.themes), themeOptions, setThemeOptions, setThemes);

      if (suggestions.tempo) {
          const t = parseInt(suggestions.tempo);
          if (!isNaN(t) && t >= 40 && t <= 220) setTempo(t);
      }
      if (suggestions.key) {
          const k = KEY_OPTIONS.find(opt => suggestions.key.includes(opt));
          if (k) setKey(k);
      }
      if (suggestions.timeSignature && TIME_SIGNATURE_OPTIONS.includes(suggestions.timeSignature)) {
          setTimeSignature(suggestions.timeSignature);
      }
      if (suggestions.lyricLanguage) {
          const l = LYRIC_LANGUAGE_OPTIONS.find(opt => suggestions.lyricLanguage.toLowerCase().includes(opt.toLowerCase()));
          if (l) setLyricLanguage(l);
      }
      if (suggestions.durationMinutes) {
          setDuration(suggestions.durationMinutes >= 6 ? "8" : "4");
      }
  };

  const handleAssistantClick = async () => {
    setAssistantLoading(true);
    setError(null);
    try {
      const isSpecificSong = songTitle.trim().length > 0;

      const prompt = `Role: Elite Music Forensic Analyst & Ethnomusicologist.
      Target: Perform a deep-dive forensic analysis of the song "${songTitle}" by "${artistRef}".

      OBJECTIVE: Achieve high accuracy on metadata by cross-referencing multiple databases (Discogs, RateYourMusic, MusicBrainz, Tunebat, Genius).

      INSTRUCTIONS:
      1. **SEARCH STRATEGY**:
         - Search " [Song Name] [Artist] genre rateyourmusic" for specific micro-genres.
         - Search " [Song Name] [Artist] bpm key tunebat" for technical data.
         - Search " [Song Name] [Artist] review" to find descriptions of instruments and atmosphere.
         - Search " [Artist] interview [Song Name]" for creative intent.

      2. **PRECISION REQUIREMENTS**:
         - **Genre/Subgenre**: Do NOT use generic terms like "Rock" if it is "Post-Hardcore with Shoegaze elements". Be SPECIFIC. Use terms like "Campursari", "Koplo", "Math Rock", "Djent", "City Pop", etc.
         - **World Music**: If traditional instruments (Gamelan, Angklung, Sitar, etc.) or styles are used, list them explicitly.
         - **Mood/Theme**: Infer deeper psychological themes from lyrics and soundscapes (e.g., "Existential Dread" instead of just "Sad").
         - **Tempo/Key**: Get the EXACT studio BPM and Key.

      3. **OUTPUT**: Return ONLY raw JSON.

      JSON TEMPLATE:
      {
        "genre": ["Main Genre 1", "Main Genre 2"], 
        "subgenre": ["Highly Specific Subgenre 1", "Fusion Style", "Micro-genre"], 
        "worldMusic": ["Specific Instrument", "Regional Style"], 
        "moods": ["Complex Mood 1", "Complex Mood 2", "Atmosphere"], 
        "themes": ["Lyrical Theme 1", "Lyrical Theme 2"], 
        "tempo": 0, 
        "key": "C Minor", 
        "timeSignature": "4/4", 
        "lyricLanguage": "Indonesian", 
        "durationMinutes": 4
      }`;

      let response;
      try {
        // Attempt 1: Gemini 3 Pro (Deep Analysis)
        response = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: { 
                tools: isSpecificSong ? [{ googleSearch: {} }] : [],
                thinkingConfig: { thinkingBudget: 2048 }, 
                responseMimeType: "application/json"
            },
        }));
      } catch (e: any) {
        if (e.message && (e.message.includes("429") || e.message.includes("quota") || e.message.includes("RESOURCE_EXHAUSTED"))) {
           console.warn("Pro model quota exceeded (429). Falling back to Gemini 3 Flash.");
           // Attempt 2: Gemini 3 Flash (Fallback)
           response = await callWithRetry(() => ai.models.generateContent({
              model: 'gemini-3-flash-preview',
              contents: prompt,
              config: { 
                  tools: isSpecificSong ? [{ googleSearch: {} }] : [],
                  // thinkingConfig not supported/needed for Flash to save quota
                  responseMimeType: "application/json"
              },
          }));
        } else {
          throw e;
        }
      }

      const suggestions = extractJSON(response.text || "");
      if (suggestions) {
          applySuggestions(suggestions);
      } else {
          throw new Error("Could not interpret AI response. Please try again.");
      }

    } catch (e: any) {
      console.error(e);
      let msg = "Assistant is busy or failed to find data. Please enter manually.";
      if (e.message && (e.message.includes("429") || e.message.includes("quota") || e.message.includes("RESOURCE_EXHAUSTED"))) {
        msg = "Daily AI quota exceeded (429). Please wait a moment or try again later.";
      }
      setError(msg);
    } finally {
      setAssistantLoading(false);
    }
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setOutputBlocks([]);
    setSources([]);

    const genreStr = genres.length > 0 ? genres.join(", ") : "General";
    const subgenreStr = subgenres.length > 0 ? subgenres.join(", ") : "General";
    const moodStr = moods.length > 0 ? moods.join(", ") : "Varied";
    const themeStr = themes.length > 0 ? themes.join(", ") : "General";
    const worldStr = worldMusicInfluences.length > 0 ? worldMusicInfluences.join(", ") : "None";

    const prompt = `ACT AS A WORLD-CLASS MUSIC PRODUCER & LYRICIST ARCHIVIST.

    *** MANDATORY USER CONFIGURATION (FORENSIC FACTS) ***
    You MUST use these exact values for the metadata tags in the output. These come from a deep forensic analysis.
    Target Song: "${songTitle}" (Artist Style: "${artistRef}")
    Genre: ${genreStr}
    Subgenre: ${subgenreStr}
    World Music Influence: ${worldStr}
    Mood: ${moodStr}
    Theme: ${themeStr}
    Tempo: ${tempo} BPM
    Key: ${key}
    Time Signature: ${timeSignature}
    Language: ${lyricLanguage}
    Duration: ${duration === "4" ? "4:00" : "8:00"}

    **CRITICAL MISSION**:
    1. **SYNCHRONIZATION**: The user provided specific fusion styles (e.g. "${subgenreStr}" / "${worldStr}"). You MUST accept these as facts. Do NOT hallucinate generic genres.
    2. **ORIGINALITY (LYRICS & STRUCTURE)**: Use Google Search to find the **OFFICIAL** lyrics and song structure for "${songTitle}" by "${artistRef}". 
       - Output the EXACT word-for-word lyrics. 
       - Follow the song's actual structure (Intro, Verse, Chorus, etc.).
    3. **ANALYSIS & LENGTH**: The total output must be **UNDER 5000 CHARACTERS**.
       - **[technical_analysis]**: MUST be EXTREMELY CONCISE (keywords/comma-separated lists only).
       - **[STYLE_DESCRIPTION_SECTION]**: MAXIMIZE THIS SECTION. Write a RICH, DETAILED, and EVOCATIVE description (approx. 800-1000 characters). **EXPLAIN WHY** the song is classified as ${subgenreStr} and how it uses ${worldStr}.
       - **[lyrics_and_arrangement]**: DO NOT TRUNCATE LYRICS.

    STRICT FORMAT TEMPLATE (START OUTPUT HERE):
    [title: ${songTitle}]
    [genre: ${genreStr}]
    [subgenre: ${subgenreStr}]
    [world music influence: ${worldStr}]
    [tempo: ${tempo} BPM]
    [key: ${key}]
    [time signature: ${timeSignature}]
    [duration: ${duration === "4" ? "4:00" : "8:00"}]
    [language: ${lyricLanguage}]
    [mood: ${moodStr}]
    [theme: ${themeStr}]

    [analysis]
    [emotion: (Brief keywords)]
    [narrative: (Brief description)]
    [rhyme_scheme: (Brief)]
    [hook: (Identify)]

    [technical_analysis]
    [structure_overview: (Concise keywords)]
    [melody: (Concise keywords)]
    [chords_verse: (Progression)]
    [chords_chorus: (Progression)]
    [rhythm: (Concise keywords)]
    [instrumentation: (Comma-separated list)]
    [production_dynamics: (Concise keywords)]
    [vocal_style: (Concise keywords)]
    [inspiration: ${artistRef}]

    [lyrics_and_arrangement]
    (Generate dynamic sections based on REAL SONG structure. Format: [Section] -> [Inst/SFX/Vocals] -> Lyrics)

    [Section Name]
    [Inst/SFX/Vocals: Brief keywords for all layers]
    (Exact Lyrics...)

    ... and so on for all sections.

    [STYLE_DESCRIPTION_SECTION]
    (Write a comprehensive, 800-1000 character essay describing the musical style, atmosphere, and production nuance. Specifically discuss the fusion of ${subgenreStr} and ${worldStr} found in the analysis.)`;

    const systemInstruction = `You are an expert Music Archivist.
    RULES:
    1. **PRIORITY**: The User's selected Genre, Subgenre, Mood, Tempo, Key, etc., are FINAL FACTS.
    2. **CONTENT**: Use Google Search to find the exact lyrics and structure.
    3. **STYLE DESCRIPTION**: This specific section must be LONG (800-1000 chars) and detailed.
    4. **TECHNICAL ANALYSIS**: This specific section must be SHORT and CONCISE.
    5. **CONSTRAINT**: Total Output MUST be < 5000 chars. Ensure full lyrics fit by compressing technical analysis.`;

    try {
      let response;
      // Attempt 1: Gemini 3 Pro
      try {
        response = await callWithRetry(() => ai.models.generateContent({
          model: 'gemini-3-pro-preview',
          contents: prompt,
          config: {
            tools: [{googleSearch: {}}],
            thinkingConfig: { thinkingBudget: 2048 },
            maxOutputTokens: 8192,
            systemInstruction: systemInstruction,
          },
        }));
      } catch (e: any) {
        if (e.message && (e.message.includes("429") || e.message.includes("quota") || e.message.includes("RESOURCE_EXHAUSTED"))) {
           console.warn("Pro model quota exceeded (429). Falling back to Gemini 3 Flash.");
           // Attempt 2: Gemini 3 Flash
           response = await callWithRetry(() => ai.models.generateContent({
              model: 'gemini-3-flash-preview',
              contents: prompt,
              config: {
                tools: [{googleSearch: {}}],
                // thinkingConfig not supported/needed for Flash to save quota
                maxOutputTokens: 8192,
                systemInstruction: systemInstruction,
              },
           }));
        } else {
          throw e;
        }
      }

      let responseText = response.text ? response.text.trim() : "";

      const startMarker = "[title:";
      const startIndex = responseText.toLowerCase().indexOf(startMarker.toLowerCase());
      if (startIndex > 0) {
        responseText = responseText.substring(startIndex);
      }

      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
          const chunks = response.candidates[0].groundingMetadata.groundingChunks;
          const uniqueSources = Array.from(new Set(chunks.map((chunk: any) => chunk.web?.uri).filter((u: any) => u))) as string[];
          setSources(uniqueSources);
      }

      const summaryMarker = '[STYLE_DESCRIPTION_SECTION]';
      const summaryIndex = responseText.lastIndexOf(summaryMarker);

      if (summaryIndex !== -1) {
        setOutputBlocks([
          { title: "Generated Music Template", content: responseText.substring(0, summaryIndex).trim() },
          { title: "Style Description", content: responseText.substring(summaryIndex + summaryMarker.length).trim() },
        ]);
      } else {
        setOutputBlocks([{ title: "Generated Music Template", content: responseText }]);
      }

    } catch (e: any) {
      console.error(e);
      let msg = `Generation failed: ${e.message || "Unknown error"}. Please try again.`;
      if (e.message && (e.message.includes("429") || e.message.includes("quota") || e.message.includes("RESOURCE_EXHAUSTED"))) {
        msg = "Daily AI quota exceeded (429). Please wait a moment or try again later.";
      }
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container">
      <header>
        <div style={{display: 'flex', justifyContent: 'flex-end', paddingBottom: '1rem'}}>
           <button onClick={handleReset} style={{background: 'none', border: 'none', color: '#666', cursor: 'pointer', fontSize: '0.8rem', textDecoration: 'underline'}}>
             Reset / Clear Data
           </button>
        </div>
        <h1>Warga Digital Studio</h1>
        <div className="promo-banner">
          <p>Create & Distribute Your Music</p>
        </div>
      </header>

      <main className="main-content">
        <section className="controls">
          <h2>Configuration</h2>
          <div className="form-group">
            <label>Song Title</label>
            <input type="text" value={songTitle} onChange={(e) => setSongTitle(e.target.value)} placeholder="e.g. Dawai Asmara" />
          </div>
          <div className="form-group">
            <label>Artist Style</label>
            <input type="text" value={artistRef} onChange={(e) => setArtistRef(e.target.value)} placeholder="e.g. Waldjinah" />
          </div>
          <button className="btn btn-secondary btn-full-width" onClick={handleAssistantClick} disabled={assistantLoading}>
            {assistantLoading ? <div className="spinner small"></div> : "Auto-Fill Suggestions (AI)"}
          </button>

          <MultiSelect 
            label="Genre" 
            options={genreOptions} 
            selected={genres} 
            onChange={setGenres} 
          />

          <MultiSelect 
            label="Subgenre" 
            options={subgenreOptions} 
            selected={subgenres} 
            onChange={setSubgenres} 
          />

          <MultiSelect 
            label="Mood" 
            options={moodOptions} 
            selected={moods} 
            onChange={setMoods} 
          />

          <MultiSelect 
            label="Theme" 
            options={themeOptions} 
            selected={themes} 
            onChange={setThemes} 
          />

          <MultiSelect 
            label="World Music Influence" 
            options={worldMusicOptions} 
            selected={worldMusicInfluences} 
            onChange={setWorldMusicInfluences} 
          />

          <div className="form-group">
            <label>Tempo (BPM): {tempo}</label>
            <input type="range" min="40" max="220" value={tempo} onChange={(e) => setTempo(parseInt(e.target.value))} />
          </div>

           <div className="form-group">
            <label>Key</label>
            <select value={key} onChange={(e) => setKey(e.target.value)}>
              {KEY_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Time Signature</label>
            <select value={timeSignature} onChange={(e) => setTimeSignature(e.target.value)}>
              {TIME_SIGNATURE_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>

          <div className="form-group">
            <label>Lyric Language</label>
            <select value={lyricLanguage} onChange={(e) => setLyricLanguage(e.target.value)}>
              {LYRIC_LANGUAGE_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
           <div className="form-group">
            <label>Duration</label>
            <div style={{display: 'flex', gap: '1rem', marginTop: '0.5rem'}}>
                <label style={{cursor: 'pointer', display: 'flex', alignItems: 'center'}}>
                    <input type="radio" value="4" checked={duration === "4"} onChange={(e) => setDuration(e.target.value)} style={{marginRight: '0.5rem', width: 'auto'}} /> ~4 min
                </label>
                <label style={{cursor: 'pointer', display: 'flex', alignItems: 'center'}}>
                    <input type="radio" value="8" checked={duration === "8"} onChange={(e) => setDuration(e.target.value)} style={{marginRight: '0.5rem', width: 'auto'}} /> ~8 min
                </label>
            </div>
          </div>

          <button className="btn btn-primary btn-full-width" onClick={handleGenerate} disabled={loading} style={{marginTop: '1.5rem'}}>
            {loading ? <div className="spinner small"></div> : "Generate Full Lyrics & Structure"}
          </button>
        </section>

        <section className="output">
          {error && <div className="error-message">{error}</div>}
          {loading && <div className="spinner-wrapper"><div className="spinner"></div><p>Composing studio arrangement...</p></div>}
          {assistantLoading && <div className="spinner-wrapper"><div className="spinner small"></div><p>Analyzing music database...</p></div>}

          {outputBlocks.length > 0 && (
            <div className="output-blocks-wrapper">
                {outputBlocks.map((block, i) => (
                    <div key={i} className="output-block">
                        <h3>{block.title}</h3>
                        <button className="btn-copy" onClick={() => navigator.clipboard.writeText(block.content)}>Copy</button>
                        <pre>{block.content}</pre>
                        {i === 0 && sources.length > 0 && (
                          <div className="info-text" style={{textAlign: 'left', borderTop: '1px solid #333', marginTop: '1rem', paddingTop: '1rem'}}>
                            <strong>Lyric Sources Used:</strong>
                            <ul>{sources.map((s, j) => <li key={j}><a href={s} target="_blank" rel="noopener noreferrer">{s}</a></li>)}</ul>
                          </div>
                        )}
                    </div>
                ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById("root")!);
root.render(<App />);
